UPDATE m_announcement
SET
    title_ja       = #{entity.titleJa}
    , title_en     = #{entity.titleEn}
    , title_es     = #{entity.titleEs}
    , body_ja      = #{entity.bodyJa}
    , body_en      = #{entity.bodyEn}
    , body_es      = #{entity.bodyEs}
    , severity     = #{entity.severity}
    , target_scope = #{entity.targetScope}
    , start_at     = #{entity.startAt}
    , end_at       = #{entity.endAt}
    , update_user_id = #{operatorUserId}
    , update_program = #{program}
WHERE
    announcement_id = #{entity.announcementId}
